		rd[i] = {x, y, z};
 	}
 	dfs1(1, 0);
 	dfs2(1, 0, 1);
 	for( int i = 1; i < n; i++ ){
		 x = rd[i].x, y = rd[i].y, z = rd[i].z;
		 if(dep[x] < dep[y]) update_len(dfn[y], dfn[y], 1, n, 1, z);
		 else update_len(dfn[x], dfn[x], 1, n, 1, z);
 	}
 	for( int i = 1; i <= m; i++ ){
		cin >> x >> y;
		lis.push_back({x, y, lca_len(x, y)});
	}
	sort(lis.begin(), lis.end(), cmp);
	lis.push_back({0, 0, 0});
	for( int i = 0; i < m; i++ ){
		road t = lis[i];
		cnt++;
